+using System;
+using System.Threading.Tasks;
+using TUnit.Assertions;
+using TUnit.Assertions.Extensions;
+using TUnit.Core;
+
+namespace @Bifrost.@Tests.@Scheduling;
+
+/// <summary>Checks the reviewed property over the supplied case domain.</summary>
+public sealed class @TestgenCoalesceAdvance
+{
+    /// <summary>Checks the property for fixture case 1.</summary>
+    /// <returns>The assertion task.</returns>
+    [Test]
+    public Task Case_1() => Check(new long[] { 639299087400000000L, 639299088000000000L, 600000000L });
+
+    /// <summary>Checks the property for fixture case 2.</summary>
+    /// <returns>The assertion task.</returns>
+    [Test]
+    public Task Case_2() => Check(new long[] { 639299028600000000L, 639299088000000000L, 600000000L });
+
+    /// <summary>Checks the property for fixture case 3.</summary>
+    /// <returns>The assertion task.</returns>
+    [Test]
+    public Task Case_3() => Check(new long[] { 639299028000000000L, 639299088000000000L, 600000000L });
+
+    /// <summary>Checks the property for fixture case 4.</summary>
+    /// <returns>The assertion task.</returns>
+    [Test]
+    public Task Case_4() => Check(new long[] { 639299027400000000L, 639299088000000000L, 600000000L });
+
+    /// <summary>Checks the property for fixture case 5.</summary>
+    /// <returns>The assertion task.</returns>
+    [Test]
+    public Task Case_5() => Check(new long[] { 639299026800000000L, 639299088000000000L, 600000000L });
+
+    /// <summary>Checks the property for fixture case 6.</summary>
+    /// <returns>The assertion task.</returns>
+    [Test]
+    public Task Case_6() => Check(new long[] { 639298998000000000L, 639299088000000000L, 600000000L });
+
+    /// <summary>Checks the property for fixture case 7.</summary>
+    /// <returns>The assertion task.</returns>
+    [Test]
+    public Task Case_7() => Check(new long[] { 639298788000000000L, 639299088000000000L, 600000000L });
+
+    /// <summary>Checks the property for fixture case 8.</summary>
+    /// <returns>The assertion task.</returns>
+    [Test]
+    public Task Case_8() => Check(new long[] { 0L, 1L, 1L });
+
+    /// <summary>Checks the property for fixture case 9.</summary>
+    /// <returns>The assertion task.</returns>
+    [Test]
+    public Task Case_9() => Check(new long[] { 0L, 304L, 3L });
+
+    /// <summary>Checks the property for fixture case 10.</summary>
+    /// <returns>The assertion task.</returns>
+    [Test]
+    public Task Case_10() => Check(new long[] { 639299027400000000L, 639299088599999999L, 600000000L });
+
+    private static async Task Check(long[] source)
+    {
+        if (!global::@Bifrost.@Tests.@Scheduling.@CoalesceBinding.@IsValid(source))
+        {
+            throw new InvalidOperationException("TestGen invalid case: source is outside the declared domain.");
+        }
+
+        long[]? follow = global::@Bifrost.@Tests.@Scheduling.@CoalesceBinding.@Advance((long[])source.Clone());
+        if (follow is null || follow.Length != source.Length || !global::@Bifrost.@Tests.@Scheduling.@CoalesceBinding.@IsValid(follow))
+        {
+            throw new InvalidOperationException("TestGen invalid case: follow-up is outside the declared domain.");
+        }
+
+        if (source.AsSpan().SequenceEqual(follow))
+        {
+            throw new InvalidOperationException("TestGen invalid case: transformation produced an identical input.");
+        }
+
+        long sourceResult = global::@Bifrost.@Tests.@Scheduling.@CoalesceBinding.@Observe(source);
+        long followResult = global::@Bifrost.@Tests.@Scheduling.@CoalesceBinding.@Observe(follow);
+        await Assert.That(global::@Bifrost.@Tests.@Scheduling.@CoalesceBinding.@Advances(source, follow, sourceResult, followResult)).IsTrue();
+    }
+}
